// Display and input validation only. Python constructs every CG matrix and
// performs the change of basis, including complex state amplitudes.
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=value=>{const n=Number(value);return !Number.isFinite(n)?'—':n===0?'0':Math.abs(n)<1e-5?n.toExponential(4):Number(n.toFixed(6)).toString();};
const parts=value=>typeof value==='number'?{re:value,im:0}:{re:Number(value?.re)||0,im:Number(value?.im)||0};
const complex=value=>{const {re,im}=parts(value);return im===0?fmt(re):re===0?`${fmt(im)}i`:`${fmt(re)} ${im<0?'−':'+'} ${fmt(Math.abs(im))}i`;};
const options=(items,value)=>items.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
const reps=[['0,0','1 · (0, 0)'],['1,0','3 · (1, 0)'],['0,1','3̄ · (0, 1)'],['2,0','6 · (2, 0)'],['0,2','6̄ · (0, 2)'],['1,1','8 · (1, 1)'],['3,0','10 · (3, 0)'],['0,3','10̄ · (0, 3)'],['2,1','15 · (2, 1)'],['1,2','15̄ · (1, 2)'],['4,0','15′ · (4, 0)'],['0,4','15̄′ · (0, 4)'],['3,1','24 · (3, 1)'],['1,3','24̄ · (1, 3)'],['2,2','27 · (2, 2)']];
const repSize=(p,q)=>(p+1)*(q+1)*(p+q+2)/2;
const size=input=>repSize(input.p1,input.q1)*repSize(input.p2,input.q2);
const limit=arithmetic=>arithmetic==='exact'?81:256;
const sizeHint=(dimension,arithmetic)=>`This space ${dimension} dimension;${arithmetic==='exact'?"precision mode upper limit 81 dimensions":"Numerical mode upper limit 256 dimensions"}。${dimension>limit(arithmetic)?"Please reduce the display or switch the mode and calculate.":"After calculation, the ground state can be selected by the complete label."}`;
const vectorHint=(dimension,arithmetic)=>`Fill in when selecting a custom vector ${dimension} items; each item is a real number or {"re": real part, "im": imaginary part}.${arithmetic==='exact'?"The real and imaginary parts can also be filled with safe expression strings, such as \"sqrt(2)/2\", \"1/3\"; i uses the im component. Python Check expression and norm.":"retains the input norm, with the squared norm ranging from 10⁻²⁴ to 10¹²; the measurement probability is normalized by the squared norm."}`;
const exactParts=value=>typeof value==='object'&&value!==null?{re:String(value.re??'0'),im:String(value.im??'0')}:{re:String(value??'0'),im:'0'};
const exactComplex=value=>{const {re,im}=exactParts(value);return im==='0'?re:re==='0'?`(${im})i`:`${re} + (${im})i`;};
export const cgName="SU(3) · CG coefficients and basis transformations";
export const cgDefault={p1:1,q1:0,p2:1,q2:0,direction:'product_to_coupled',state:{index:1}};
export const cgPresets={
  'cg-three-three':{experiment:'su3_cg',input:{...cgDefault}},
  'cg-three-bar':{experiment:'su3_cg',input:{p1:1,q1:0,p2:0,q2:1,direction:'product_to_coupled',state:{index:2}}},
  'cg-eight-eight':{experiment:'su3_cg',input:{p1:1,q1:1,p2:1,q2:1,direction:'product_to_coupled',state:{index:7}}},
  'cg-complex':{experiment:'su3_cg',input:{...cgDefault,state:{amplitudes:Array.from({length:9},(_,index)=>({re:index===1?Math.SQRT1_2:0,im:index===3?Math.SQRT1_2:0}))}}},
  'cg-ten-three':{experiment:'su3_cg',input:{p1:3,q1:0,p2:1,q2:0,arithmetic:'numeric',direction:'product_to_coupled',state:{index:1}}},
  'cg-exact-ten-three':{experiment:'su3_cg',input:{p1:3,q1:0,p2:1,q2:0,arithmetic:'exact',direction:'product_to_coupled',state:{index:1}}},
  'cg-twentyseven-three':{experiment:'su3_cg',input:{p1:2,q1:2,p2:1,q2:0,arithmetic:'exact',direction:'product_to_coupled',state:{index:1}}},
  'cg-exact-three-bar':{experiment:'su3_cg',input:{p1:1,q1:0,p2:0,q2:1,arithmetic:'exact',direction:'product_to_coupled',state:{index:2}}},
  'cg-exact-complex':{experiment:'su3_cg',input:{...cgDefault,arithmetic:'exact',state:{amplitudes:Array.from({length:9},(_,index)=>({re:index===1?'sqrt(2)/2':'0',im:index===3?'sqrt(2)/2':'0'}))}}},
};
export const cgInputIds=['#lg-cg-rep1','#lg-cg-rep2','#lg-cg-arithmetic','#lg-cg-direction','#lg-cg-mode','#lg-cg-index','#lg-cg-vector'];
export function cgControls(input){
  const custom=Array.isArray(input.state?.amplitudes),dimension=size(input),arithmetic=input.arithmetic||'numeric';
  return `<label>calculation mode<select id="lg-cg-arithmetic">${options([['numeric',"numerical value · Higher dimensional representation （≤256 dimension)"],['exact',"Exact · Rational numbers and radicals （≤81 dimensions)"]],arithmetic)}</select></label>${[1,2].map(i=>`<label>No. ${i} SU(3) means <select id="lg-cg-rep${i}">${options(reps,`${input['p'+i]},${input['q'+i]}`)}</select></label>`).join('')}<label>change of basis Direction<select id="lg-cg-direction">${options([['product_to_coupled',"product basis → coupling basis （C†）"],['coupled_to_product',"coupling basis → product basis (C)"]],input.direction)}</select></label><label>input mode<select id="lg-cg-mode">${options([['basis',"a ground state"],['vector',"Custom complex amplitude vector"]],custom?'vector':'basis')}</select></label><label>Input base index (starting from 0)<input id="lg-cg-index" type="number" min="0" max="${dimension-1}" step="1" value="${custom?0:esc(input.state?.index??0)}"><span class="lg-muted" id="lg-cg-size-hint" role="status">${sizeHint(dimension,arithmetic)}</span></label><label class="lg-cg-vector-label">complex amplitude vector (JSON)<textarea id="lg-cg-vector" rows="4" spellcheck="false" placeholder='[1, 0, {"re":"sqrt(2)/2","im":"1/3"}, …]'>${custom?esc(JSON.stringify(input.state.amplitudes)):''}</textarea><span class="lg-muted" id="lg-cg-vector-hint">${esc(vectorHint(dimension,arithmetic))}</span></label><div class="lg-presets"><button type="button" data-lg-physics-preset="cg-three-three">CG · 3 ⊗ 3</button><button type="button" data-lg-physics-preset="cg-three-bar">CG · 3 ⊗ 3̄</button><button type="button" data-lg-physics-preset="cg-eight-eight">CG · 8 ⊗ 8</button><button type="button" data-lg-physics-preset="cg-complex">complex phase superposition</button><button type="button" data-lg-physics-preset="cg-ten-three">high-dimensional · 10 ⊗ 3</button><button type="button" data-lg-physics-preset="cg-exact-ten-three">accurate · 10 ⊗ 3</button><button type="button" data-lg-physics-preset="cg-twentyseven-three">accurate · 27 ⊗ 3</button><button type="button" data-lg-physics-preset="cg-exact-three-bar">accurate · 3 ⊗ 3̄</button><button type="button" data-lg-physics-preset="cg-exact-complex">Accurate complex phase and round trip</button></div><p class="lg-hint">Each input representation satisfies p + q ≤ 4; the selected mode also limits the total dimensionality of the product space. Exact mode performs symbolic operations directly from GT generator , and the first calculation will load SymPy. The coefficients adopt the base, phase and replica conventions given in this experiment.</p>`;
}
function readReps($){
  const input={};for(const i of [1,2]){const value=$('#lg-cg-rep'+i)?.value;if(!reps.some(([id])=>id===value))throw Error("Please select SU(3) in the list to represent （p + q ≤ 4）.");[input['p'+i],input['q'+i]]=value.split(',').map(Number);}return input;
}
export function readCGPayload($,read){
  const input=readReps($),direction=$('#lg-cg-direction')?.value,mode=$('#lg-cg-mode')?.value,dimension=size(input),arithmetic=$('#lg-cg-arithmetic')?.value||'numeric';
  if(!['numeric','exact'].includes(arithmetic))throw Error("Please select numerical or precise calculation mode.");
  if(dimension>limit(arithmetic))throw Error(`This product space ${dimension} dimension, more than${arithmetic==='exact'?"accurate":"value"}mode ${limit(arithmetic)} dimension upper limit; please reduce the representation${arithmetic==='exact'?"or switch to numerical mode":''}。`);
  if(!['product_to_coupled','coupled_to_product'].includes(direction))throw Error("Please select a valid change of basis direction.");
  if(!['basis','vector'].includes(mode))throw Error("Please select a ground state or custom complex amplitude vector.");
  let state;
  if(mode==='basis')state={index:read('#lg-cg-index',0,dimension-1,true)};
  else{
    let amplitudes;try{amplitudes=JSON.parse($('#lg-cg-vector')?.value||'');}catch{throw Error("complex amplitude vector needs to be a valid JSON array.");}
    if(!Array.isArray(amplitudes)||amplitudes.length!==dimension)throw Error(`The complex amplitude vector must contain ${dimension} item is consistent with the dimension of this space.`);
    const finite=value=>typeof value==='number'&&Number.isFinite(value)&&Math.abs(value)<=1e6*(1+1e-12);
    if(arithmetic==='exact'){
      const scalar=value=>typeof value==='number'&&Number.isFinite(value)&&Math.abs(value)<=1e6||typeof value==='string'&&value.trim().length>0&&value.length<=65536&&/^[\d\s+*/()\-]+$/.test(value.replaceAll('sqrt',''));
      if(amplitudes.some(value=>typeof value==='number'||typeof value==='string'?!scalar(value):!value||Array.isArray(value)||typeof value!=='object'||Object.keys(value).some(key=>!['re','im'].includes(key))||!scalar(Object.hasOwn(value,'re')?value.re:0)||!scalar(Object.hasOwn(value,'im')?value.im:0)))throw Error("The precise amplitude must be a real number or a safe expression string, allowing integers, rational numbers, four arithmetic operations and sqrt (non-negative integers); please use re and im objects to fill in complex numbers.");
      state={amplitudes:amplitudes.map(value=>typeof value==='object'?{re:value.re??0,im:value.im??0}:{re:value,im:0})};
      if(state.amplitudes.reduce((sum,z)=>sum+Object.values(z).reduce((n,value)=>n+(typeof value==='string'?value.length:0),0),0)>1048576)throw Error("The total length of expressions for exact input vectors is limited to 1 MiB.");
      return {...input,arithmetic,direction,state};
    }
    if(amplitudes.some(value=>typeof value==='number'?!finite(value):!value||Array.isArray(value)||typeof value!=='object'||Object.keys(value).some(key=>!['re','im'].includes(key))||!finite(Object.hasOwn(value,'re')?value.re:0)||!finite(Object.hasOwn(value,'im')?value.im:0)))throw Error("Each entry must be a finite real number or a complex object containing only re and im, with magnitude at most 10⁶.");
    const squaredNorm=amplitudes.reduce((sum,value)=>{const z=parts(value);return sum+z.re*z.re+z.im*z.im;},0);if(squaredNorm<1e-24*(1-1e-12)||squaredNorm>1e12*(1+1e-12))throw Error("input state must be between 10⁻²⁴ and 10¹² (the boundary adopts the 10⁻¹² relative tolerance).");
    state={amplitudes:amplitudes.map(parts)};
  }
  return {...input,...(arithmetic==='exact'?{arithmetic}:{}),direction,state};
}
// Refresh labels and index bounds without discarding the other form fields.
export function bindCGControls(root,current){
  const $=selector=>root.querySelector(selector),refresh=()=>{if(!current())return;try{const dimension=size(readReps($)),index=$('#lg-cg-index'),arithmetic=$('#lg-cg-arithmetic').value;index.max=String(dimension-1);if(Number(index.value)>=dimension)index.value='0';const mode=$('#lg-cg-mode').value;index.disabled=mode==='vector';$('#lg-cg-vector').disabled=mode!=='vector';$('#lg-cg-size-hint').textContent=sizeHint(dimension,arithmetic);$('#lg-cg-size-hint').className=dimension>limit(arithmetic)?'lg-muted lg-cg-limit':'lg-muted';$('#lg-cg-vector-hint').textContent=vectorHint(dimension,arithmetic);}catch{/* Submission explains invalid injected values. */}};
  for(const id of ['#lg-cg-rep1','#lg-cg-rep2','#lg-cg-mode','#lg-cg-arithmetic'])if($(id))$(id).onchange=refresh;
  refresh();
}

const basisLabel=(item,index)=>item?.label||`base ${index}`;
const table=(labels,values,caption,probabilities=null,exactValues=null,exactProbabilities=null)=>`<div class="lg-table-scroll"><table class="lg-data-table lg-cg-amplitudes"><caption>${esc(caption)}</caption><thead><tr><th>Index · Substrate Label</th>${exactValues?"<th>precise amplitude</th><th>numerical approximation</th>":"<th>complex amplitude</th>"}<th>${probabilities?"normalized probability":"| Amplitude |²"}</th></tr></thead><tbody>${values.map((value,index)=>({value,index,z:parts(value)})).filter(({z,index})=>exactValues?exactComplex(exactValues[index])!=='0':probabilities?probabilities[index]>1e-20:Math.hypot(z.re,z.im)>1e-10).map(({value,index,z})=>`<tr><td>${index} · ${esc(basisLabel(labels[index],index))}</td>${exactValues?`<td class="lg-cg-exact"><code>${esc(exactComplex(exactValues[index]))}</code></td>`:''}<td>${esc(complex(value))}</td><td>${exactProbabilities?`<code class="lg-cg-exact">${esc(exactProbabilities[index])}</code><br>≈ `:''}${fmt(probabilities?probabilities[index]:z.re*z.re+z.im*z.im)}</td></tr>`).join('')}</tbody></table></div>`;
function matrixHeatmap(result){
  const n=result.dimension,cell=360/n,step=n<=12?1:Math.ceil(n/12);
  return `<svg class="lg-visual lg-cg-heatmap" viewBox="0 0 470 450" role="img" aria-label="CG change of basis Matrix heat map: rows are product bases and columns are coupling bases"><title>Complete CG matrix; blue is the positive real part, orange is the negative real part, and the color depth represents the absolute value. Hover to see the coefficients.</title><text x="246" y="22" text-anchor="middle" class="lg-svg-label">column: coupled base index</text><rect x="66" y="58" width="360" height="360" fill="#f4f6ef"/>${Array.from({length:n},(_,i)=>i).filter(i=>i%step===0||i===n-1).map(i=>`<text x="${66+(i+.5)*cell}" y="46" text-anchor="middle" class="lg-cg-axis">${i}</text><text x="56" y="${58+(i+.65)*cell}" text-anchor="end" class="lg-cg-axis">${i}</text>`).join('')}${result.cgMatrix.flatMap((row,i)=>row.map((value,j)=>{const z=parts(value),m=Math.min(1,Math.hypot(z.re,z.im));if(m<1e-10)return '';return `<rect x="${66+j*cell}" y="${58+i*cell}" width="${cell}" height="${cell}" fill="${Math.abs(z.im)>1e-10?'#82629c':z.re<0?'#b7863c':'#4383a2'}" fill-opacity="${.2+.8*m}"><title>C[${i}, ${j}] = ${esc(result.exactCGMatrix?.[i]?.[j]??complex(value))}; ${esc(basisLabel(result.productBasis[i],i))} ← ${esc(basisLabel(result.coupledBasis[j],j))}</title></rect>`;})).join('')}<rect x="66" y="58" width="360" height="360" fill="none" stroke="#cad8bf"/><text x="246" y="443" text-anchor="middle" class="lg-svg-label">row: product basis index; C = ⟨ product basis | coupling basis ⟩</text></svg>`;
}
function slice(result,direction,index){
  const column=direction==='column',values=column?result.cgMatrix.map(row=>row[index]):result.cgMatrix[index],labels=column?result.productBasis:result.coupledBasis,exactValues=result.exactCGMatrix?(column?result.exactCGMatrix.map(row=>row[index]):result.exactCGMatrix[index]):null;
  return `<p class="lg-hint">${column?"Expansion of selected coupled states in a product basis: a column of C.":"The coefficients of the selected product state to each coupling state: one row of C takes the conjugate."}${exactValues?"C in this convention is a real matrix; exact tables omit only strictly zero entries.":"amplitude retains sign and phase; items below 10⁻¹⁰ are omitted from the table."}</p>${table(labels,column?values:values.map(value=>{const z=parts(value);return {re:z.re,im:-z.im};}),column?basisLabel(result.coupledBasis[index],index):basisLabel(result.productBasis[index],index),null,exactValues)}`;
}
function completeMatrix(result,page=0){
  const n=result.dimension,paged=n>64,start=paged?page*16:0,end=paged?Math.min(n,start+16):n;
  return `${paged?`<label class="lg-filter">coefficient table row range<select id="lg-cg-matrix-page">${options(Array.from({length:Math.ceil(n/16)},(_,i)=>[i,`${i*16}–${Math.min(n-1,i*16+15)} OK`]),page)}</select></label><p class="lg-hint">total ${n} OK,${n} column; paged by 16 rows, all coefficients retained in JSON export.</p>`:''}<div class="lg-table-scroll lg-cg-full-matrix"><table class="lg-data-table"><caption>Row: Product basis; Column: Coupling basis.${result.exactCGMatrix?"displays the exact radical formula;":"displays numerical value;"}The complete label is preserved in the JSON export along with the exact results.</caption><thead><tr><th>i / j</th>${result.coupledBasis.map((item,j)=>`<th title="${esc(basisLabel(item,j))}">${j}</th>`).join('')}</tr></thead><tbody>${result.cgMatrix.slice(start,end).map((row,local)=>{const i=start+local;return `<tr><th title="${esc(basisLabel(result.productBasis[i],i))}">${i}</th>${row.map((value,j)=>`<td>${esc(result.exactCGMatrix?.[i]?.[j]??complex(value))}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div>`;
}
function blockTable(result){
  return `<details class="lg-generator"><summary>Irreducible components, copies and column indexes</summary><div class="lg-table-scroll"><table class="lg-data-table lg-cg-blocks"><thead><tr><th>means (p, q)</th><th>copy</th><th>matrix column</th><th>exchange parity</th></tr></thead><tbody>${(result.blocks||[]).map(block=>`<tr><td>${esc(block.label)} (${block.p}, ${block.q})</td><td>${esc(block.copy)}</td><td>${block.start}–${block.end-1}</td><td><span class="lg-cg-parity">${block.swapParity===1?"+ Symmetry":block.swapParity===-1?"− Antisymmetric":"Not applicable"}</span></td></tr>`).join('')}</tbody></table></div><p class="lg-hint">The direct product of the same factors can distinguish components according to commutative parity; the two eight-dimensional copies of 8 ⊗ 8 take symmetric and antisymmetric embeddings respectively. The weights within each replica are still differentiated by the base label. Changing the phase of the basis vector alone changes the sign of the CG amplitude.</p></details>`;
}
export function cgOutput(result){
  const outputBasis=result.direction==='coupled_to_product'?result.productBasis:result.coupledBasis,exact=Array.isArray(result.exactCGMatrix);
  const checkNames={unitarity:"unitary residual",intertwining:"generator interleaved residual",roundtrip:"round trip change of basis residual",stateNorm:"norm residual",weightConservation:"weight conservation residual",exchange:"Exchange symmetric residuals"};
  return `<pre class="lg-formula">${esc(result.decompositionText||`${result.factors.map(factor=>factor.label).join(' ⊗ ')} = ${result.blocks.map(block=>block.label).join(' ⊕ ')}`)}
| Coupling basis ⟩ = | Product basis ⟩ C
a coupling = C† a product; a product = C a coupling
The</pre>
    <p class="lg-cg-mode-result">${exact?"Exact symbolic mode · Rational numbers and radicals":"Double precision numerical mode"} · ${result.dimension} × ${result.dimension}</p><p>matrix is constructed from Python. First observe the expansion of the input state, and then view other Clebsch–Gordan coefficients by row or column.</p>
    ${exact?`<p class="lg-cg-exact-norm">Exact norm squared:<code>${esc(result.exactInputNorm)}</code> → <code>${esc(result.exactOutputNorm)}</code></p>`:''}
    <p class="lg-cg-norm">${exact?"value verification:":"Input norm squared "}${fmt(result.inputNorm)} → ${exact?'':"Output norm square "}${fmt(result.outputNorm)}. Python preserves the overall scale of the input amplitude; the table probabilities are normalized by the square of the norm.</p>
    ${table(outputBasis,result.outputAmplitudes,"The non-zero amplitude after this change of basis",result.outputProbabilities,result.exactOutputAmplitudes,result.exactOutputProbabilities)}
    <button type="button" class="secondary" id="lg-cg-reverse-state">Take output vector as input, reverse change of basis</button>${exact?"<p class=\"lg-hint\">The reverse operation directly transfers the exact expression of the above table, retaining the complex phase of the entire state.</p>":''}
    <details class="lg-generator"><summary>Check this input status</summary>${table(result.direction==='coupled_to_product'?result.coupledBasis:result.productBasis,result.inputAmplitudes,"input amplitude and base",result.inputProbabilities,result.exactInputAmplitudes,result.exactInputProbabilities)}</details>
    ${blockTable(result)}<div class="lg-cg-matrix-section"><h4>View one by one Clebsch–Gordan coefficients</h4><label class="lg-filter">Select coupling basis (view matrix columns)<select id="lg-cg-column">${options(result.coupledBasis.map((item,i)=>[i,`${i} · ${basisLabel(item,i)}`]),0)}</select></label><button type="button" class="secondary" id="lg-cg-use-column">Take this coupled state as the initial state and change to the product basis</button><div id="lg-cg-column-panel">${slice(result,'column',0)}</div><label class="lg-filter">Select product base (view matrix rows)<select id="lg-cg-row">${options(result.productBasis.map((item,i)=>[i,`${i} · ${basisLabel(item,i)}`]),0)}</select></label><button type="button" class="secondary" id="lg-cg-use-row">Take this product state as the initial state and change to the coupling basis</button><div id="lg-cg-row-panel">${slice(result,'row',0)}</div><details class="lg-generator" id="lg-cg-map-details"><summary>Expand the complete matrix heat map</summary><div id="lg-cg-map-panel"></div></details><details class="lg-generator" id="lg-cg-matrix-details"><summary>Expand the complete coefficient table (${result.dimension} × ${result.dimension}）</summary><div id="lg-cg-matrix-panel"></div></details></div>
    ${exact?`<section class="lg-cg-exact-checks" aria-label="accurate symbol verification"><h4>accurate symbol verification</h4><p>The following is the residual obtained by the symbolic operation of Python; 0 means that the identity relationship is accurately established.</p><div class="lg-checks">${Object.entries(result.exactChecks||{}).map(([name,value])=>`<div><span>${esc(checkNames[name]||name)}</span><code>${esc(value)}</code></div>`).join('')}</div></section>`:''}
    <div class="lg-checks">${Object.entries(result.checks||{}).map(([name,value])=>`<div><span>${exact?"numerical verification · ":''}${esc(checkNames[name]||name)}</span><code>${Number.isFinite(Number(value))?Number(value).toExponential(2):esc(value)}</code></div>`).join('')}</div><details class="lg-generator"><summary>The basis for this calculation is the same as phase convention</summary>${(Array.isArray(result.convention)?result.convention:[result.convention||'']).map(note=>`<p>${esc(note)}</p>`).join('')}<ol>${(result.derivation||[]).map(step=>`<li>${esc(step)}</li>`).join('')}</ol></details>`;
}
export function bindCGOutput(root,result,current,runWithInput){
  const $=selector=>root.querySelector(selector),valid=selector=>{const value=Number($(selector)?.value);return Number.isInteger(value)&&value>=0&&value<result.dimension?value:null;};
  const arithmetic=result.exactCGMatrix?'exact':'numeric';
  const reverse=$('#lg-cg-reverse-state');if(reverse)reverse.onclick=()=>{if(!current()||typeof runWithInput!=='function')return;return runWithInput({arithmetic,direction:result.direction==='product_to_coupled'?'coupled_to_product':'product_to_coupled',state:{amplitudes:result.exactOutputAmplitudes?result.exactOutputAmplitudes.map(exactParts):result.outputAmplitudes.map(value=>({...parts(value)}))}});};
  for(const [kind,id] of [['column','#lg-cg-column'],['row','#lg-cg-row']]){
    const control=$(id);if(control)control.onchange=()=>{if(!current())return;const index=valid(id);if(index!==null)$(id+'-panel').innerHTML=slice(result,kind,index);};
    const button=$('#lg-cg-use-'+kind);if(button)button.onclick=()=>{if(!current())return;const index=valid(id);if(index!==null&&typeof runWithInput==='function')return runWithInput({arithmetic,direction:kind==='column'?'coupled_to_product':'product_to_coupled',state:{index}});};
  }
  for(const [id,panel,render] of [['#lg-cg-map-details','#lg-cg-map-panel',matrixHeatmap],['#lg-cg-matrix-details','#lg-cg-matrix-panel',completeMatrix]]){
    const details=$(id);let rendered=false;if(details)details.ontoggle=()=>{if(!current()||!details.open||rendered)return;const draw=page=>{if(!current())return;$(panel).innerHTML=render(result,page);const pages=$('#lg-cg-matrix-page');if(pages)pages.onchange=()=>{const value=Number(pages.value);if(Number.isInteger(value)&&value>=0&&value<Math.ceil(result.dimension/16))draw(value);};};draw(0);rendered=true;};
  }
}
